mapper.select:
SELECT id, content, type, difficulty, tags, source, source_type, import_hash, option_a, option_b, option_c, option_d, correct_answer, analysis, solution_strategy, category_id, status, created_at, updated_at FROM question WHERE status = 1 AND type != 3
AND category_id IN
#{categoryId}
AND source_type = #{sourceType}
ORDER BY id

SELECT id, content, type, difficulty, tags, source, source_type, import_hash, option_a, option_b, option_c, option_d,
       correct_answer, analysis, solution_strategy, category_id, status, created_at, updated_at
FROM question
WHERE type != 3

    AND (content LIKE CONCAT('%', #{keyword}, '%') OR tags LIKE CONCAT('%', #{keyword}, '%') OR source LIKE CONCAT('%', #{keyword}, '%'))


    AND category_id IN

        #{categoryId}



    AND status = #{status}


    AND type = #{type}


    AND difficulty = #{difficulty}


    AND source_type = #{sourceType}

ORDER BY created_at DESC

SELECT COUNT(1)
FROM question
WHERE import_hash = #{question.importHash}
